package br.com.dmp.widget
import android.app.PendingIntent
import android.appwidget.AppWidgetProvider
import android.appwidget.AppWidgetManager
import android.app.job.JobInfo
import android.app.job.JobScheduler
import android.content.ComponentName
import android.content.Context
import android.content.Intent
import android.net.Uri
import android.os.Bundle
import android.graphics.Color
import android.view.View
import android.widget.RemoteViews
import org.json.JSONObject
import org.json.JSONArray
import java.time.LocalDate
open class TodayWidget:AppWidgetProvider(){
 override fun onUpdate(c:Context,m:AppWidgetManager,ids:IntArray){renderAll(c);schedule(c)}
 override fun onEnabled(c:Context){schedule(c)}
 override fun onDisabled(c:Context){val m=AppWidgetManager.getInstance(c);if(m.getAppWidgetIds(ComponentName(c,TodayWidget::class.java)).isEmpty()&&m.getAppWidgetIds(ComponentName(c,AgendaWidget::class.java)).isEmpty())(c.getSystemService(Context.JOB_SCHEDULER_SERVICE) as JobScheduler).apply{cancel(100);cancel(101)}}
 override fun onDeleted(c:Context,ids:IntArray){ids.forEach{WidgetSettings.remove(c,it)}}
 override fun onAppWidgetOptionsChanged(c:Context,m:AppWidgetManager,id:Int,o:Bundle){renderAll(c)}
 override fun onReceive(c:Context,i:Intent){super.onReceive(c,i);if(i.action==Intent.ACTION_BOOT_COMPLETED){renderAll(c);schedule(c)};if(i.action=="br.com.dmp.widget.REFRESH")schedule(c)}
 companion object{
  fun schedule(c:Context){val s=c.getSystemService(Context.JOB_SCHEDULER_SERVICE) as JobScheduler;val job=ComponentName(c,RefreshJob::class.java);s.schedule(JobInfo.Builder(100,job).setRequiredNetworkType(JobInfo.NETWORK_TYPE_ANY).setPeriodic(1800000).setPersisted(true).build());s.schedule(JobInfo.Builder(101,job).setRequiredNetworkType(JobInfo.NETWORK_TYPE_ANY).setMinimumLatency(0).build())}
  private fun link(c:Context,id:Int,slot:String,path:String?,base:String?,home:String?):PendingIntent{val uri=if(path!=null&&WidgetSettings.safePath(path)&&base!=null)base+path else home;val i=if(uri==null)Intent(c,ConfigureActivity::class.java)else Intent(Intent.ACTION_VIEW,Uri.parse(uri));i.data=i.data?:Uri.parse("dmp-widget://configure/$id/$slot");return PendingIntent.getActivity(c,("$id-$slot").hashCode(),i,PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE)}
  private fun row(c:Context,text:String,color:Int,path:String?,id:Int,slot:String,base:String?,home:String?)=RemoteViews(c.packageName,R.layout.widget_row).apply{setTextViewText(R.id.row_text,text);setTextColor(R.id.row_text,color);setOnClickPendingIntent(R.id.row_text,link(c,id,slot,path,base,home))}
  fun renderAll(c:Context){val store=SecureStore(c);val snapshot=try{store.get("snapshot")?.let{JSONObject(it)}}catch(_:Exception){null};val connection=store.connection();val base=connection?.optString("base");val home=connection?.optString("home");val manager=AppWidgetManager.getInstance(c);for(agenda in arrayOf(false,true)){val provider=if(agenda)AgendaWidget::class.java else TodayWidget::class.java;for(id in manager.getAppWidgetIds(ComponentName(c,provider))){val v=RemoteViews(c.packageName,if(agenda)R.layout.agenda_widget else R.layout.widget);val today=snapshot?.optJSONObject("today")?:snapshot;val data=if(agenda)snapshot?.optJSONObject("agenda") else today;val date=data?.optString("date")?.takeIf{it.isNotBlank()}?:LocalDate.now(java.time.ZoneId.of("America/Sao_Paulo")).toString();val height=manager.getAppWidgetOptions(id).getInt(AppWidgetManager.OPTION_APPWIDGET_MIN_HEIGHT,if(agenda)400 else 490);val alpha=255*WidgetSettings.opacity(WidgetSettings.value(c,id,"opacity",90))/100;v.setImageViewBitmap(R.id.background,WidgetSettings.background(manager.getAppWidgetOptions(id).getInt(AppWidgetManager.OPTION_APPWIDGET_MIN_WIDTH,280),height,alpha));v.setTextViewText(R.id.date,WidgetRules.day(date));v.setTextViewText(R.id.updated,(if(store.get("offline")=="1")"Sem conexão · " else "Atualizado ")+(data?.optString("updatedAt")?.takeIf{it.isNotBlank()}?.let{try{WidgetRules.updated(it)}catch(_:Exception){"—"}}?:"—"));v.setOnClickPendingIntent(R.id.header,link(c,id,"home","/app?widget=home&date=$date",base,home));v.setOnClickPendingIntent(R.id.open,link(c,id,"open",null,base,home));v.setOnClickPendingIntent(R.id.agenda,link(c,id,"agenda","/app?widget=agenda&date=$date",base,home));v.setOnClickPendingIntent(R.id.settings,PendingIntent.getActivity(c,id,Intent(c,WidgetSettingsActivity::class.java).putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,id).setData(Uri.parse("dmp-widget://settings/$id")),PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE));v.setOnClickPendingIntent(R.id.refresh,PendingIntent.getBroadcast(c,id,Intent(c,provider).setAction("br.com.dmp.widget.REFRESH"),PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE));if(agenda){v.removeAllViews(R.id.items);v.setOnClickPendingIntent(R.id.add,link(c,id,"new","/app?widget=new&date=$date",base,home));val items=data?.optJSONArray("items")?:JSONArray();val filtered=(0 until items.length()).map{items.getJSONObject(it)}.filter{WidgetSettings.flag(c,id,"tomorrow",true)||it.optString("date")==date};val cap=WidgetSettings.capacity(height,WidgetSettings.value(c,id,"items",8));for((index,e) in filtered.take(cap).withIndex()){val prefix=if(e.optString("date")==date)"Hoje" else "Amanhã";val time=if(e.optBoolean("allDay"))"Dia inteiro"else e.optString("start")+"–"+e.optString("end");val text="$prefix · $time\n${e.optString("title")} · ${e.optString("type")}";v.addView(R.id.items,row(c,text,try{Color.parseColor(e.optString("color"))}catch(_:Exception){Color.rgb(23,61,53)},e.optString("destination"),id,"item-$index",base,home))};if(filtered.isEmpty())v.addView(R.id.items,row(c,if(data==null)"Conecte o DMP; atualize após a publicação." else "Sem itens neste período",Color.DKGRAY,null,id,"empty",base,home));v.setTextViewText(R.id.more,if(filtered.size>cap)"+${filtered.size-cap} itens · Abrir agenda"else "");v.setOnClickPendingIntent(R.id.more,link(c,id,"more","/app?widget=agenda&date=$date",base,home))}else{val links=today?.optJSONObject("links");for((name,viewId) in mapOf("programmed" to R.id.programmed,"attended" to R.id.attended,"absent" to R.id.absent,"remaining" to R.id.remaining)){val label=mapOf("programmed" to "Programados","attended" to "Atendidos","absent" to "Ausências","remaining" to "Faltam")[name];v.setTextViewText(viewId,"${today?.optInt(name)?.toString()?:"—"}  $label");v.setOnClickPendingIntent(viewId,link(c,id,name,links?.optString(name)?:"/app/widget?widget=$name&date=$date",base,home))};val next=today?.optJSONObject("next");v.setTextColor(R.id.next,try{Color.parseColor(next?.optString("color")?:"#173D35")}catch(_:Exception){Color.rgb(23,61,53)});v.setTextViewText(R.id.next,if(next==null)"Sem próximos atendimentos hoje"else "Próximo: ${next.optString("time")} · ${next.optString("title")}\n${next.optString("type")}${next.optString("category").takeIf{it!="null"&&it.isNotBlank()}?.let{" · $it"}?:""}");v.setOnClickPendingIntent(R.id.next,link(c,id,"next",next?.optString("destination"),base,home));v.removeAllViews(R.id.workouts);val workouts=today?.optJSONArray("workouts")?:JSONArray();val take=if(height>=610)2 else 1;v.addView(R.id.workouts,row(c,"Treinos do dia"+(if(workouts.length()>take)" · +${workouts.length()-take}"else ""),Color.rgb(23,61,53),"/app?widget=performance&date=$date",id,"workout-title",base,home));for(n in 0 until minOf(workouts.length(),take)){val e=workouts.getJSONObject(n);v.addView(R.id.workouts,row(c,e.optString("type")+" · "+e.optString("title"),Color.rgb(23,103,75),e.optString("destination"),id,"workout-$n",base,home))};if(workouts.length()==0)v.addView(R.id.workouts,row(c,"Nenhum treino registrado",Color.GRAY,"/app?widget=performance&date=$date",id,"no-workouts",base,home));v.removeAllViews(R.id.notes);v.setViewVisibility(R.id.notes,if(WidgetSettings.flag(c,id,"notes",true))View.VISIBLE else View.GONE);val notes=today?.optJSONArray("commitments")?:JSONArray();if(WidgetSettings.flag(c,id,"notes",true)){v.addView(R.id.notes,row(c,"Compromissos"+(if(notes.length()>take)" · +${notes.length()-take}"else ""),Color.rgb(23,61,53),"/app?widget=home&date=$date",id,"notes-title",base,home));for(n in 0 until minOf(notes.length(),take)){val e=notes.getJSONObject(n);v.addView(R.id.notes,row(c,(e.optString("time").takeIf{it!="null"}?:"")+" · "+e.optString("title"),Color.rgb(23,103,75),e.optString("destination"),id,"note-$n",base,home))};if(notes.length()==0)v.addView(R.id.notes,row(c,if(today?.optString("commitmentsStatus")=="unavailable")"Compromissos indisponíveis"else if(today?.optString("commitmentsStatus")=="not_configured")"Todoist não configurado"else "Sem compromissos hoje",Color.GRAY,null,id,"no-notes",base,home))};v.removeAllViews(R.id.calendar);val calendar=WidgetSettings.flag(c,id,"calendar",true)&&height>=500;v.setViewVisibility(R.id.calendar,if(calendar)View.VISIBLE else View.GONE);if(calendar){val d=LocalDate.parse(date);v.addView(R.id.calendar,row(c,d.format(java.time.format.DateTimeFormatter.ofPattern("MMMM yyyy",java.util.Locale.forLanguageTag("pt-BR"))),Color.rgb(23,61,53),"/app?widget=agenda&date=$date",id,"month",base,home));val first=d.withDayOfMonth(1);val offset=first.dayOfWeek.value%7;var cell=0;for(week in 0..5){val line=RemoteViews(c.packageName,R.layout.calendar_week);for(slot in 0..6){val n=cell++-offset+1;val cellId=intArrayOf(R.id.day0,R.id.day1,R.id.day2,R.id.day3,R.id.day4,R.id.day5,R.id.day6)[slot];if(n in 1..d.lengthOfMonth()){val key=first.withDayOfMonth(n).toString();line.setTextViewText(cellId,n.toString());line.setTextColor(cellId,if(key==date)Color.rgb(23,103,75)else Color.DKGRAY);line.setOnClickPendingIntent(cellId,link(c,id,"day-$n","/app?widget=agenda&date=$key",base,home))}else line.setTextViewText(cellId,"")};v.addView(R.id.calendar,line)}}};manager.updateAppWidget(id,v)}}}
 }
}
class AgendaWidget:TodayWidget()
